/* AppNotice01Mapper.countDailyUser */
SELECT
    COUNT(1)
FROM TB_DAILY_USER D
WHERE D.CMPNY_CD = #{cmpnyCd}
  AND D.USER_CD = #{userCd}
  AND D.USE_YN = 'Y'

/* AppNotice01Mapper.selectPopupNoticeList */ SELECT N.NOTICE_ID AS noticeId , N.TITLE AS title , N.CONTENT AS content , N.PIN_YN AS pinYn , N.POPUP_FROM_YMD AS popupFromYmd , N.POPUP_TO_YMD AS popupToYmd , DATE_FORMAT(N.INSERT_DATE, '%Y-%m-%d %H:%i') AS insertDate , ( SELECT COUNT(1) FROM TB_NOTICE_FILE NF WHERE NF.CMPNY_CD = N.CMPNY_CD AND NF.NOTICE_ID = N.NOTICE_ID ) AS fileCnt , 10 AS isDaily FROM TB_NOTICE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.NOTICE_TYPE = 'NOTICE' AND N.DEL_YN = 'N' AND N.POPUP_YN = 'Y' AND DATE_FORMAT(NOW(), '%Y%m%d') BETWEEN N.POPUP_FROM_YMD AND N.POPUP_TO_YMD
AND NOT EXISTS ( SELECT 1 FROM TB_NOTICE_USER_ACK A WHERE A.CMPNY_CD = N.CMPNY_CD AND A.NOTICE_ID = N.NOTICE_ID AND A.USER_CD = #{gvUserCd} AND A.ACK_TYPE = 'SNOOZED' AND A.SNOOZE_UNTIL_YMD >= DATE_FORMAT(NOW(), '%Y%m%d') )
AND ( N.PIN_YN = 'Y' OR NOT EXISTS ( SELECT 1 FROM TB_NOTICE_USER_ACK A2 WHERE A2.CMPNY_CD = N.CMPNY_CD AND A2.NOTICE_ID = N.NOTICE_ID AND A2.USER_CD = #{gvUserCd} AND A2.ACK_TYPE = 'CONFIRMED' ) ) ORDER BY N.PIN_YN DESC, N.PIN_ORDER ASC, N.INSERT_DATE DESC LIMIT 10

/* AppNotice01Mapper.selectMyNoticeList */ SELECT N.NOTICE_ID AS noticeId , N.TITLE AS title , N.PIN_YN AS pinYn , DATE_FORMAT(N.INSERT_DATE, '%Y-%m-%d %H:%i') AS insertDate , ( SELECT COUNT(1) FROM TB_NOTICE_FILE NF WHERE NF.CMPNY_CD = N.CMPNY_CD AND NF.NOTICE_ID = N.NOTICE_ID ) AS fileCnt
, CASE WHEN ( N.POPUP_YN = 'Y' AND DATE_FORMAT(NOW(),'%Y%m%d') BETWEEN N.POPUP_FROM_YMD AND N.POPUP_TO_YMD ) THEN CASE WHEN NOT EXISTS ( SELECT 1 FROM TB_NOTICE_USER_ACK A2 WHERE A2.CMPNY_CD = N.CMPNY_CD AND A2.NOTICE_ID = N.NOTICE_ID AND A2.USER_CD = #{gvUserCd} AND A2.ACK_TYPE = 'CONFIRMED' ) THEN 1 ELSE 0 END ELSE CASE WHEN K.LAST_READ_DATE IS NULL THEN 1 ELSE 0 END END AS isUnread , CASE WHEN N.PIN_YN = 'Y' THEN 1 ELSE 0 END AS isImportant FROM TB_NOTICE N LEFT OUTER JOIN TB_NOTICE_USER_ACK K ON K.CMPNY_CD = N.CMPNY_CD AND K.NOTICE_ID = N.NOTICE_ID AND K.USER_CD = #{gvUserCd} WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.NOTICE_TYPE = 'NOTICE' AND N.DEL_YN = 'N'
ORDER BY N.PIN_YN DESC, N.PIN_ORDER ASC, N.INSERT_DATE DESC

/* AppNotice01Mapper.countNoticeVisibleToUser */
SELECT
    COUNT(1)
FROM TB_NOTICE N
WHERE N.CMPNY_CD = #{cmpnyCd}
  AND N.NOTICE_ID = #{noticeId}
  AND N.NOTICE_TYPE = 'NOTICE'  
  AND N.DEL_YN = 'N'

/* AppNotice01Mapper.selectNoticeInsertNo */
SELECT
    N.INSERT_NO
FROM TB_NOTICE N
WHERE N.CMPNY_CD = #{cmpnyCd}
  AND N.NOTICE_ID = #{noticeId}
  AND N.NOTICE_TYPE = 'NOTICE'  
  AND N.DEL_YN = 'N'

mapper.insert:
/* AppNotice01Mapper.upsertNoticeAck */
INSERT INTO TB_NOTICE_USER_ACK
(
    CMPNY_CD
  , NOTICE_ID
  , USER_CD
  , ACK_TYPE
  , SNOOZE_UNTIL_YMD
  , LAST_READ_DATE
  , INSERT_NO
  , INSERT_DATE
)
VALUES
(
    #{gvCmpnyCd}
  , #{noticeId}
  , #{gvUserCd}
  , #{ackType}
  , #{snoozeUntilYmd}
  , NOW()
  , #{gvUserCd}
  , NOW()
) AS NEW
ON DUPLICATE KEY UPDATE
    ACK_TYPE         = NEW.ACK_TYPE
  , SNOOZE_UNTIL_YMD = NEW.SNOOZE_UNTIL_YMD
  , LAST_READ_DATE   = NOW()
  , UPDATE_NO        = #{gvUserCd}
  , UPDATE_DATE      = NOW()

/* AppNotice01Mapper.upsertNoticeRead */
INSERT INTO TB_NOTICE_USER_ACK
(
    CMPNY_CD
  , NOTICE_ID
  , USER_CD
  , ACK_TYPE
  , LAST_READ_DATE
  , INSERT_NO
  , INSERT_DATE
)
VALUES
(
    #{gvCmpnyCd}
  , #{noticeId}
  , #{gvUserCd}
  , 'READ'
  , NOW()
  , #{gvUserCd}
  , NOW()
) AS NEW
ON DUPLICATE KEY UPDATE
    LAST_READ_DATE = NOW()
  , UPDATE_NO      = #{gvUserCd}
  , UPDATE_DATE    = NOW()
